{
  "name": "paginator",
  "description": "Generic pagination algorithm wrapped in a CommonJS module",
  "version": "1.0.0",
  "author": {
    "name": "Conrad Pankoff",
    "email": "deoxxa@fknsrs.biz",
    "url": "http://www.fknsrs.biz/"
  },
