  "repository": { "type":"git", "url":"git://github.com/deoxxa/paginator.git" },
  "keywords": [
    "paginator",
    "pagination",
    "pages"
  ],
  "main": "./index",
  "scripts": {
    "pre-publish": "docco index.js"
  }
